import React from 'react';
import StarRating from './components/StarRating';
import './App.css';

function App() {
  return (
    <div className="app">
      <h1>Rate this course</h1>
      <p className="app__hint">
        Hover over a star to preview your rating. Click to lock it in.
      </p>
      <StarRating max={5} />
    </div>
  );
}

export default App;

