import React from 'react';

function Star({ value, state, onMouseEnter, onClick }) {
  const className = `star${state === 'full' ? ' filled' : ''}`;
  return (
    <button
      type="button"
      className={className}
      data-testid={`star-${value}`}
      aria-label={`Star ${value}`}
      onMouseEnter={onMouseEnter}
      onClick={onClick}
    >
      ★
    </button>
  );
}

export default Star;

