import React from 'react';
import { useStarRating } from '../hooks/useStarRating';
import { getStarState } from '../utils/rating';
import Star from './Star';

function StarRating({ max = 5, initialValue = 0 }) {
  const { rating, hoverValue, preview, stopPreview, commit } = useStarRating(
    max,
    initialValue
  );

  // While the pointer is over the row, show the previewed value;
  // otherwise fall back to the committed rating.
  const activeValue = hoverValue !== null ? hoverValue : rating;

  const handleClick = (value) => {
    // TODO(you): clicking a star should permanently set the rating to `value`.
    // The `commit` function from the hook is intended for exactly this.
  };

  return (
    <div className="star-rating" data-rating={rating}>
      <div className="star-rating__row" onMouseLeave={() => stopPreview()}>
        {Array.from({ length: max }, (_, i) => {
          const value = i + 1;
          const state = getStarState(value, activeValue);
          return (
            <Star
              key={value}
              value={value}
              state={state}
              onMouseEnter={() => preview(value)}
              onClick={() => handleClick(value)}
            />
          );
        })}
      </div>
      <p className="star-rating__label">
        {activeValue > 0 ? `${activeValue} / ${max} stars` : 'No rating yet'}
      </p>
    </div>
  );
}

export default StarRating;

src/hooks/useStarRating.js.contents:
import { useState } from 'react';
import { clampRating } from '../utils/rating';

export function useStarRating(max = 5, initialValue = 0) {
  const [rating, setRating] = useState(() => clampRating(initialValue, max));
  const [hoverValue, setHoverValue] = useState(null);

  // Show a preview while the pointer is over a star, without committing it.
  const preview = (value) => setHoverValue(value);

  // Should ONLY clear the in-progress preview and leave `rating` untouched.
  const stopPreview = () => {
    // BUG: the hover preview leaks into the committed rating.
    // Leaving the row currently overwrites `rating` with the previewed value
    // instead of discarding the preview.
    if (hoverValue !== null) {
      setRating(hoverValue);
    }
    setHoverValue(null);
  };

  // Persists a clicked star's value as the permanent rating.
  const commit = (value) => {
    // TODO(you): make `value` the permanent rating, clamped to [0, max],
    // and clear any in-progress hover preview.
  };

  return { rating, hoverValue, preview, stopPreview, commit };
}

export default useStarRating;

src/utils/rating.js.contents:
// Clamps a rating value into [min, max]. A rating can never dip below 0 or
// rise above the total number of stars.
export function clampRating(value, max, min = 0) {
  if (value < min) return min;
  if (value > max) return max;
  return value;
}

// Maps a single star's position against the currently active value:
// 'full' when the star is at or below the active value, otherwise 'empty'.
export function getStarState(value, activeValue) {
  return value <= activeValue ? 'full' : 'empty';
}

