import { describe, test, expect } from 'vitest';
import { render, fireEvent } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import StarRating from '../src/components/StarRating';
import { clampRating } from '../src/utils/rating';

const getStars = (container) =>
  Array.from(container.querySelectorAll('[data-testid^="star-"]'));

const isFilled = (star) => star.classList.contains('filled');

const getRating = (container) =>
  Number(container.querySelector('.star-rating').getAttribute('data-rating'));

const expectFillState = (container, filledCount, message) => {
  const stars = getStars(container);
  for (let i = 0; i < stars.length; i += 1) {
    const shouldBeFilled = i < filledCount;
    if (isFilled(stars[i]) !== shouldBeFilled) {
      throw new Error(
        `${message}: star ${i + 1} should be ${shouldBeFilled ? 'filled' : 'empty'}`
      );
    }
  }
};

describe('Star Rating widget', () => {
  test('renders the correct number of stars', () => {
    const { container } = render(<StarRating max={7} />);
    const stars = getStars(container);
    if (stars.length !== 7) {
      throw new Error(`Expected 7 stars, got ${stars.length}`);
    }
  });

  test('shows no filled stars by default, and honors a provided initial rating', () => {
    const defaults = render(<StarRating max={5} />);
    expectFillState(defaults.container, 0, 'default render');

    const seeded = render(<StarRating max={5} initialValue={3} />);
    expectFillState(seeded.container, 3, 'initialValue={3} render');
  });

  test('clicking a star sets the rating to that star value', () => {
    const { container } = render(<StarRating max={5} />);
    const stars = getStars(container);
    fireEvent.click(stars[2]); // click star 3
    if (getRating(container) !== 3) {
      throw new Error(
        `Expected rating 3 after clicking star 3, got ${getRating(container)}`
      );
    }
    expectFillState(container, 3, 'after committing star 3');
  });

  test('hovering previews a rating without committing it', () => {
    const { container } = render(<StarRating max={5} />);
    const stars = getStars(container);
    fireEvent.mouseEnter(stars[3]); // hover star 4
    expectFillState(container, 4, 'while hovering star 4');
    if (getRating(container) !== 0) {
      throw new Error(
        `Hover must not change the committed rating (expected 0, got ${getRating(container)})`
      );
    }
  });

  test('moving the mouse away reverts to the committed rating', () => {
    const { container } = render(<StarRating max={5} initialValue={2} />);
    const stars = getStars(container);
    const row = container.querySelector('.star-rating__row');
    fireEvent.mouseEnter(stars[4]); // hover star 5
    fireEvent.mouseLeave(row); // move the mouse away
    if (getRating(container) !== 2) {
      throw new Error(
        `Rating leaked to ${getRating(container)} after mouse leave; expected 2`
      );
    }
    expectFillState(container, 2, 'after leaving the rating row');
  });

  test('rating is never clamped below 0 or above max', () => {
    if (clampRating(-3, 5) !== 0) {
      throw new Error('clampRating(-3, 5) should be 0');
    }
    if (clampRating(12, 5) !== 5) {
      throw new Error('clampRating(12, 5) should be 5');
    }
    if (clampRating(4, 5) !== 4) {
      throw new Error('clampRating(4, 5) should be 4');
    }
  });
});
